def solve(inputs: dict) -> float:
    g = inputs.get('g')
    x = inputs.get('x')
    p = inputs.get('p')

    result = 1
    base = g % p

    while x > 0:
        if (x % 2) == 1:
            result = (result * base) % p
        base = (base * base) % p
        x = x // 2

    return float(result)
